//! Google Sheets API v4 implementation.//!//! All API calls go through the host's HTTP capability, which handles//! credential injection and rate limiting. The WASM tool never sees//! the actual OAuth token.use crate::near::agent::host;use crate::types::*;const SHEETS_API_BASE: &str = "https://sheets.googleapis.com/v4/spreadsheets";/// Make a Google Sheets API call.fn api_call(method: &str, path: &str, body: Option<&str>) -> Result<String, String> {    let url = if path.is_empty() {        SHEETS_API_BASE.to_string()    } else {        format!("{}/{}", SHEETS_API_BASE, path)    };    let headers = if body.is_some() {        r#"{"Content-Type": "application/json"}"#    } else {        "{}"    };    let body_bytes = body.map(|b| b.as_bytes().to_vec());    host::log(        host::LogLevel::Debug,        &format!("Google Sheets API: {} {}", method, url),    );    let response = host::http_request(method, &url, headers, body_bytes.as_deref(), None)?;    if response.status < 200 || response.status >= 300 {        let body_text = String::from_utf8_lossy(&response.body);        return Err(format!(            "Google Sheets API returned status {}: {}",            response.status, body_text        ));    }    if response.body.is_empty() {        return Ok(String::new());    }    String::from_utf8(response.body).map_err(|e| format!("Invalid UTF-8 in response: {}", e))}/// Parse sheet info from the API's JSON.fn parse_sheet_info(v: &serde_json::Value) -> SheetInfo {    let props = &v["properties"];    let grid = &props["gridProperties"];    SheetInfo {        sheet_id: props["sheetId"].as_i64().unwrap_or(0),        title: props["title"].as_str().unwrap_or("").to_string(),        index: props["index"].as_i64().unwrap_or(0),        row_count: grid["rowCount"].as_i64().unwrap_or(0),        column_count: grid["columnCount"].as_i64().unwrap_or(0),    }}/// Parse a named range from the API's JSON.fn parse_named_range(v: &serde_json::Value) -> NamedRange {    let range = &v["range"];    let range_str = format_grid_range(range);    NamedRange {        named_range_id: v["namedRangeId"].as_str().unwrap_or("").to_string(),        name: v["name"].as_str().unwrap_or("").to_string(),        range: range_str,    }}/// Format a GridRange into a human-readable string.fn format_grid_range(v: &serde_json::Value) -> String {    let sheet_id = v["sheetId"].as_i64().unwrap_or(0);    let start_row = v["startRowIndex"].as_i64().unwrap_or(0);    let end_row = v["endRowIndex"].as_i64().unwrap_or(0);    let start_col = v["startColumnIndex"].as_i64().unwrap_or(0);    let end_col = v["endColumnIndex"].as_i64().unwrap_or(0);    format!(        "sheetId={}, rows {}:{}, cols {}:{}",        sheet_id, start_row, end_row, start_col, end_col    )}/// Create a new spreadsheet.